export const DEFAULT_TEMPLATE = "<!-- tf-pr-commenter:detail -->\n<details><summary>📋 <code><%= it.stack.name %></code><% if (it.stack.countsLine) { %> <code><%= it.stack.countsLine %></code><% } %><% if (it.stack.driftCount) { %> ⚠️ <%= it.stack.driftCount %> drifted<% } %><% if (it.stack.outputsCount) { %> Δ <%= it.stack.outputsCount %> outputs<% } %></summary>\n\n<% if (it.stack.actionsText) { %>```diff\n<%~ it.stack.actionsText + '\\n' %>\n```\n\n<% } %><% if (it.stack.driftText) { %>**⚠️ Changed outside Terraform:**\n\n```diff\n<%~ it.stack.driftText + '\\n' %>\n```\n\n<% } %><% if (it.stack.outputsText) { %>**Δ Output changes:**\n\n```diff\n<%~ it.stack.outputsText + '\\n' %>\n```\n\n<% } %></details>\n<!-- tf-pr-commenter:shell -->\n<%/*\nEta's default autoTrim ('nl') removes one newline after each closing tag.\nKeep two blank lines after the H2 line below so one survives before the table.\n*/%>\n<% if (it.stacks.length === 0) { %>\n## <%= it.header %>\n\n✅ No stacks with changes to plan.\n<% } else { %>\n## <%= it.header %> — <%= it.stacks.length %> stack<%= it.stacks.length === 1 ? '' : 's' %>\n\n\n| Stack | Plan | Status |\n|---|---|---|\n<% it.stacks.forEach((stack) => { %>| `<%= stack.name %>` | <%~ stack.planCell %> | <%= stack.statusIcon %><% if (stack.driftCount) { %> ⚠️ <%= stack.driftCount %> drifted<% } %><% if (stack.outputsCount) { %> Δ <%= stack.outputsCount %> outputs<% } %> |\n<% }) %><% if (it.detailSections.length) { %>\n\n<%~ it.detailSections.join('\\n\\n') %>\n<% } %><% if (it.omittedCount > 0) { %>\n\n> ⚠️ Plan detail for <%= it.omittedCount %> stack<%= it.omittedCount === 1 ? '' : 's' %> omitted to fit the comment size limit — see each job's step summary. Counts above are complete.\n<% } %><% } %>\n"
